import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"漢上易傳卷六","description":"漢上易傳 - 漢上易傳卷六","frontmatter":{"title":"漢上易傳卷六","description":"漢上易傳 - 漢上易傳卷六"},"headers":[],"relativePath":"classics/hanshang/007.md","filePath":"classics/hanshang/007.md"}'),n={name:"classics/hanshang/007.md"};function r(c,p,_,i,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="漢上易傳卷六" tabindex="-1">漢上易傳卷六 <a class="header-anchor" href="#漢上易傳卷六" aria-label="Permalink to “漢上易傳卷六”">​</a></h1><p>翰林學士、左朝奉大夫知制誥兼侍讀、兼資善堂翊善、長林縣開國男、食邑三佰戶、賜紫金魚袋朱震集傅 ䷶ 離下，震上。 豐，亨，王假之，勿憂宜，日中。彖曰：豐，大也。明以動，故豐。王假之，尚大也。勿憂宜，日中，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？</p><p>豐，泰九二之四也。乾變離明，坤易震動，明以動則亨，亨則大，豐大也，故曰豐亨。彖曰：豐，大也，明以動故豐。此合兩體言致豐之道也。假，至也。乾在上之象。王者明以動，其道亨，乃能至於豐大。九二上行至四，王假之也。王假之者，尚大也。四海之廣，萬物之眾，無一物不得其所，無一夫不獲自盡，非小道之所能至，故曰王假之，尚大也。此以九四言乎豐之才也。二四失位為憂，離下有伏坎為加憂。離見坎伏，勿憂也。然明以動勿憂，其至於大也。進而至於五，則得位矣，故曰勿憂。此以九二之四言乎豐之才也。離日震動，日當五為中，曰動於下，升於東方，明動不巳，九四進五，何憂乎不至於中而無所不照哉。日之大明，萬物鹹睹，宜，照天下也。乾為天，五離應二，照天下也。太玄曰：日正於天，何為也？曰：君子乘位，為車為馬，車軨馬𩡺，可以周天下，故利其為主也。宜日中則正於天，利其為主之謂也。故曰勿憂宜日中，宜照天下也。此以九二進而至五，言乎豐之才也。五復降四，坎離象變，離成兌，日在西，日中則昃也。坎成兌，巽兌為口，月闕於巽辛，月盈則食也。四乾陽長於震，二坤陰生於離，陽長，盈也，息也。陰生則盈者虛，消者息矣。有天地，然後有人，有鬼神。鬼神往來於天地之間者也。豐大之時，所宜憂者，不在乎未中，而常在乎日之既中也。何則？日中俄且昃矣，月盈俄且食矣。盈者必虛，息者必消。天地之所不能違者，時也。而況天地之間，聚而為人，散而為鬼神乎？明動不巳，未有能保其大者也。保此道者，其唯中乎！故曰：日中則昃，月盈則食。天地盈虛，與時消息，而況於人乎？況於鬼神乎。此復以坎離升降明豐之戒也。在卦氣為六月，故太玄準之以大廓。</p><p>象曰：雷電皆至，豐，君子以折獄致刑。</p><p>雷電皆至，萬物豐大之時，豐則生訟，故君子法其威明，並用以治刑獄。電明照也，所以折獄。雷，威怒也，所以致刑。折獄者，以正折其不正。初二三正也，而二有伏，坎為獄不明，則枉者不伸。致刑者，刑其不正而巳。四五不正也。兌為刑殺不威，則小人不懼。噬嗑其明在上，君子在上之事也，故為明罰飭法。豐用明在下，君子在下之事也，故為折獄致刑。</p><p>初九，遇其配主，雖旬無咎，往有尚。象曰：雖旬無咎，過旬災也。</p><p>泰九二之四成豐，故九四為豐之主。配者陰陽相匹，孟氏、鄭氏本作妃，嘉耦曰妃。妃，嫓也，亦匹配之意。初九，九四，陽也；六五，陰也。初與四不應，六五亦無應，四雖不應，初可因四為主而配五，陰陽相配，故九四為配主。遇者不期而會，四不應初，而初九主之，不期於會而會，故曰遇其配主。旬，均也。初九、九四，均也。然明動相資，致豐之道，非明則動無所之，非動則明無所用，是以均而無咎。無咎者，初九以正相資也。初九遇四，往而相易以致用，則初得尚於五，而豐之道上行矣。尚亦配也，與尚於中行之尚同，故曰往有尚也。夫初九遇九四，所以得尚於五者，以正相資而成豐。譬之共難，則仇怨恊力，勢使之然。若妄動不正，過四而有其位，明動不相為用，過旬也。過旬則失其配主，往而無所尚，與坎險相會，災至矣。豐道亡，所以災也，故曰過旬災也。初動有小過象，故曰過旬。謂之均者，六甲周行乘八節，其數四百八十而成鈞。鈞，勻也。初九，離納巳，九四震納庚。自巳至庚凡十日，十日週而復始，故訓勻。</p><p>六二，豐其蔀，日中見鬥，往，得疑疾，有孚發若，吉。象曰：有孚發若，信以發志也。</p><p>震巽為草，二在草中，有周匝掩蔽之意，故曰蔀。陸震曰：曆法凡十九年，閏分盡為一章，四章凡七十六年為一蔀，五蔀週六甲，凡三百八十年而曆象小成。豐蔀之名，蓋寓此意。離目為見，豐為日中，五兌伏艮，艮離為天文，賁之象也。震少陽，其策七。震為動，有星在上，動於中而其數七，鬥之象也。二有至明中正之才，以豐時遇闇弱不正之君，猶當晝而夜，至於見鬥，其昏甚矣。坤為冥，晦暗之象。五既不能下賢，二自往見，反得疑疾。自往者，亦取疑之道。巽為不果，六五陰失位，疾也。然二五相應之地，有孚之理，二積中正，不巳盡其誠信以感發其志，則五動而應之乃吉。易傳曰：苟誠意能動，雖昏蒙可開也。雖柔弱可輔也。雖不正可正也。古之人事庸君常主而克行其道者，巳之誠上達而君見信之篤耳。</p><p>九三，豐其沛，日中見沬，折其右肱，無咎。象曰：豐其沛，不可大事也。折其右肱，終不可用也。沛，古本作旆，正弼以為幡幔，震為玄黃，兌，金斷之旆也。幡幔圍蔽於內，故豐其旆。沬，鬥後小星，微昧之光，子夏傳及字林作昧。三之上成艮，艮離為天文。星在鬥之後，隨鬥而動者。昧也。三明極而剛正，處豐之昧。上六暗極矣。猶日中當明，而反見鬥後之星，其暗尤甚。巽為事，陽為大，伏坎為可。豐尚大也。豐其旆，往見則不明，故退而守正，以不可大事故也。兌為右，伏艮為肱。兌折之。折右肱也。上六暗極，不可用之，以有為從之，必罹其咎，故自折其右肱，示終不可用則無咎。</p><p>九四，豐其蔀，日中見鬥，遁其夷主，吉。象曰：豐其蔀，位不當也；日中見鬥，幽不明也；遇其夷主，吉行也。</p><p>四動成坎離，光明也；不動成震巽，震巽為草，掩蔽周匝，蔀也。四在蔀中，處不當位，自蔽其光明，故曰豐其蔀。兌有伏艮，四應離初，艮離為天文，震，動也。其策七，有星動於上而其數七之象。離目為見，四處不常位，又不能變，若動而交初，則幽者明矣。坎為隱伏故也。以此處豐，猶日中之時而反見鬥，處幽暗而巳不明，故曰幽不明也。九四不正，其不明自取之，異於二三矣。夷主者，謂初也。九四與初九均為陽，而上下不敵，四忘其勢，下夷於初。四者，初之所主也，故曰夷主初正，正則吉。初九助四而上行，以資其明，吉行也。易傳曰：居大臣之位，得在下之賢，同德相輔，其助豈小也哉！</p><p>六五，來章，有慶譽，吉。象曰：六五之吉，有慶也。</p><p>六五屈體，來下於四，與之共天位。九四之明，上行之五，相錯成離，坤離為文，章者，文之成也。九四上行，則初應四，二應五，三應上，六爻並用，成豐大之慶。五屈巳下賢，四志行乎上人，自譽之。兌為口譽之者也。五得正，吉也。</p><p>上六，豐其屋，蔀其家，𬮭其戶，闃其無人，三歲不覿，兇。象曰：豐其屋，天際翔也。𬮭其戶，闃其無人，自藏也。</p><p>自二至上，體大壯，棟宇之象。上六動陰，變陽為大。豐其屋，言自處高大也。二為家，震巽為草，豐盛周匝以掩蔽之。蔀其家，言所居不明也。自處高大，所居不明，以高亢自絕於人，如飛鳥務上翔於天際，豈復能降哉？上動成離，離為飛鳥，乾為天，在外卦之際，天際也。豐之時，九四忘其敵，巳下資初，九三與上六正應也，其能忘乎？故三自下往，庶幾發其昏暗，知處豐之道。九三離目為見往𬮭之，坤戶闔而不應，闃寂乎其無人聲，太玄所謂外大抗，中無人也。三於是退而自藏於坎中。乾為歲，三自四歷三爻，三歲不覿也。豐其屋，蔀其家，自絕於人也。三歲不覿，人絕之也。上六動不正，兇也。不直曰兇者，有應焉，猶冀乎下交也。至於三歲不覿，人亦厭之，而兇至矣。𬮭，小見也。覿，私見也。自上六言之，謂之窺，陰為小也。自九三之上言之，謂之覿，私見也。私不正也。䷷ 艮下，離上。 旅小亨旅貞吉。彖曰：旅，小亨，柔得中乎外而順乎剛，止而麗乎明，是以小亨旅貞吉也。旅之時義大矣哉！</p><p>旅，否之變也。剛當居上，柔當居下。六居五，失其所居而在外，旅也。然六居五，柔得中矣。得中，則其柔不過，得為旅之中道。易傳曰：中非一揆，旅有旅之中也。柔得中，則能順乎上下之剛，不為剛所揜而小者亨。順乎剛而柔失中，旅道窮矣。坤，順也。君子入國，問禁興之日，從新國之法，順乎剛也，故曰柔得中而順乎剛。此以六五言旅小亨也。九居三，未為失其所居也。然剛自五而反居於下，猶為旅也。居三成艮，屈其剛而止於下，自謙屈之道也。雖止乎下矣，然九三正止而不失其正，上麗乎離之明。君子之居是邦也，事其大夫之賢者，友其士之仁者，麗乎明也。正然後能麗乎明，不正，人將拒我矣。正則吉，故曰止而麗乎明。此以九三言旅貞吉也。旅，難處也。旅如六五，柔得中乎外而順乎剛，在我者不失巳矣，乃可以小亨。旅如九三，止而麗乎明，在彼者亦不失人矣，乃可以貞吉。是以旅一也。而再言之。易傳曰：旅困之時，非陽剛中正，有助於下，則不能致大亨。如卦之才，則可以小亨，得旅貞而吉也。四方固男子之事，居者必有旅也，顧處之如何耳。夫子歷國應聘，嘗去父母之邦矣，去他國矣，欲浮於海，居九夷矣，蓋得旅之時義也。旅之時不一，而義者時措之宜。知其時而不知其宜，不可也。非大人孰能盡之？故曰旅之時義大矣哉。在卦氣為四月，故太玄準之以裝</p><p>象曰：山上有火，旅，君子以明慎用刑，而不留獄。</p><p>山上有火，明而止，止而不處，旅也。君子之用刑也，雖明而止，故明而慎於用刑；雖止而不處，故亦不留獄。明者或不慎，慎者或留獄，失旅之象也。離有伏坎為獄兌，為刑殺，艮止慎也。</p><p>初六，旅瑣瑣，斯其所取災。象曰：旅瑣瑣，志窮災也。鄭曰：瑣瑣，小也。艮為小，動而之四，覆成艮，小之又小。瑣，瑣也。初六，小人之旅，卑柔而不中正，恃應而求於四者，褻，其細巳甚，故曰旅瑣。瑣四巽極而燥，火性炎上，不能容初。艮。止也。厭止妄動，往而復止，人亦厭之，志窮也。坎險災也。志窮遇險，斯其所取災也。艮為手，有求取之象，楚申侯是巳。曰斯曰其者，初四上下皆艮手，取災之象，故指兩爻言之。</p><p>六二，旅即次，懷其資，得童僕貞。象曰：得童僕貞，終無尢也。</p><p>艮，止也。二得位，止而得位，即次舍也。離兌為蠃，貨貝資財之象。二巽為入，懷其資也。童僕，一本作僮僕，艮為少男，初卑陰賤，二在上，畜之童僕也。初於二，得童僕貞也。童僕貞，則二親信之而不疑。旅在下，柔而中正，即次所遇而安也。懷其資，得三、四、五之助也。又得童僕貞，貞而下承之，旅如是多助矣。故動而之外，終無尢之之者。五兌為口，尢之者也。初六不正而曰貞者，貞於二也，貞於主人，二巽東南，主人位也。歸妹九二利幽人之貞，貞於五也。童僕貞，然後次舍可止，資貨可有。夫子曰：審其所以從之之謂貞也。</p><p>九三，旅焚其次，喪其童僕，貞厲。象曰：旅焚其次，亦以傷矣矣。以旅與下其義喪也。</p><p>艮，止也。五得位，止而得位。次，舍也。巽木離火，焚其次也。九三在旅而過剛，四五之所不與，則失其所止，有焚其次之象。兌為毀傷也。旅失其所止，亦可傷也。初艮為童僕，九三既失其所止，以旅之故，乃巽而與下，失尊卑之宜。初三易位，初失其正，喪其童僕，貞也。所以喪者，為旅之義。剛柔皆失中，旅如是，寡助，危矣。六居三不正，危之道。</p><p>九四，旅於處，得其資斧，我心不快。象曰：旅於處，未得位也。得其資斧，心未快也。</p><p>二三止而得位為次舍，四巽為入而未得位，行者處而巳，入對出言之為處，九四非安處也，故曰旅於處。離兌為蠃，具資也。離為兵，巽木貫之，斧也。得其資以為利，得其斧以為斷。上得乎五，下得乎三之助矣。九剛明之才，而處四履謙，能下善處乎旅，故得上下之利。有資貨焉，有器用焉。雖不若六二，亦曰得其所矣。然未得位也。上不足以發五之志，下不足以致九二之賢，雖得資斧，未免為旅人，故我心不快。兌為決，中為心，四進而上，道行於五而二應，則快矣。孟子曰：久於齊，非我志也。</p><p>六五，射雉，一矢亡，終以譽命。象曰：終以譽命，上逮也。五在旅卦，不取君象，君不可旅也。離為雉，雉，文明之物。文明，人文也，聖人止亂而不以威武者也。離為兵，伏坎為弓，伏艮為手，兵加之弓，上矢也。矢者，射雉之器，五動，弓矢發，離坎毀而雉亡，一矢亡之也。一矢亡雉者，五得中道，動而心中乎理之象。然六五未當位，雖有文明之德，未可以動，上九屈體逮之，則令譽升聞而爵命之矣。兌口在下，與之譽也。巽為命，上卦之終，由譽而後命之始也。未當位，終也譽命，故曰終以譽命。五進上，其在賓師之位，乾西北賓之位也。</p><p>上九，鳥焚其巢，旅人先笑後號，啕，喪牛於易，兇。象曰：以旅在上，其義焚也。喪牛於易，終莫之聞也。上九，離為飛鳥，九動變六成震巽，巽為木，震為竹葦，鳥隱其中，巢也。上九極剛，以高亢居上，非旅人之宜。巽木離火，鳥焚其巢，失其所也。離目動震有聲，笑也。樂其未焚之前，柔順謙下時也。兌澤流於目，巽號出於口，哀於既焚之後，悔其先之時也。上與三相應之地，上六變而正成坤，坤為牛。九三應而上降三，二成坎，坎為耳。上九高亢不變坤象隱，喪牛也。易，輕易也。火性剽疾，上九極剛，輕易也，故曰喪牛於易。九喪柔順，三不往應，坎耳伏矣。輕易者，自塞其耳而聰不明也。陸機羈旅：處群士之上，而不聞牽秀、孟玖之毀，其以高亢輕易而致禍乎，䷸ 巽下，巽上。 巽，小亨，利有攸往，利見大人。彖曰：重巽以申命，剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。</p><p>柔在下而承二剛，巽也。巽為風，風者，天之號令，命者，天之令也，故巽為命。內巽者，命之始，外巽者巽而達乎外，申前之命也。重巽之象，唯可施之於申命。先儒謂上下皆巽，不違其令，命乃行也。若施之於佗，則巽已甚矣，故曰重巽以申命。此以兩體而言巽也。巽自遁來，訟之變，六三之四，上下皆巽。九二之剛，巽乎中也；九五之剛，巽乎中正也。巽乎中正，則其剛不過，而所施當乎人心，是以志行乎上下，故曰剛中正而志行。此以三、四相易而言九二、九五之巽也。九二之剛巽乎正，則初六之柔順之；九五之剛巽乎中正，則六四之柔順之。上下之柔皆順乎剛，則物無違者而也。二、九五之志行，故曰柔皆順乎剛。此以初六、六四言，大者巽，則小者無不順也。柔皆順乎剛，雖無違者，然順乎中正乃善，不然，失所從矣。六四離目為見大人者，九五剛而巽乎中正者也。剛巽乎中正而柔順之，則柔者亦得其正，而小者亨矣，豈非小者之利乎。故曰利見大人。此以九五言巽之利也。小者亨矣，故六四利有攸往，利見大人。而其道上行，故曰是以小亨，利有攸往，利見大人。徐氏王昭素考王弼注有命乃行也四字，當在重巽以申命之下，疑象或脫文，理若有之，在卦氣為七月，故大玄準之以翕。</p><p>象曰：隨風巽，君子以申命行事。</p><p>巽為風，風巽而入者也。前後相隨而至，則歲事行矣，故巽又有事之象。傳言八風之至，各以四十五日而成一歲是也。君子申命諄諄者，行事也。行事莫如巽，巽則易入。初六進退科武人之貞。象曰：進退，志疑也。利武人之貞，志治也。</p><p>巽初，行事之始也。居卑體柔，不能自立，過於巽者也。退則不安，進則無應，又二剛據之，莫知所從，巽為不果，故曰進退志疑也。六變九巽成乾，應兌，乾為健，兌為決疑，志去矣。健決者，武人之貞。天道尚右，故兌為武人。志疑者，不先治其志也。君子自治其動以正，行之以健決，確乎不可移，雖千萬人必往，孰能奪其志哉。故曰利武人之貞。志治也。巽為工，有治之意。易傳曰：治謂修立也。九二，巽在床下，用史巫紛若，吉。無咎。象曰：紛若之吉，得中也。</p><p>巽初，坤變乾也。巽為木，坤西南方，乾為人，設木於西南之奧而人即安焉者，床也。巽股變艮股，見手伏蒲，伏於床下之象。九二不正，卑巽如此，宜有咎。然九二剛中，其動也正，卑巽者，非為利也，將以誠意感動九五而巳，故用史巫紛若吉。吉者，正也。九二之動，上之五成震，震為聲。五之二成兌，兌為言。上九宗廟，兌口出聲，祝史道人之意，以達於鬼神之象。六降於二，巫以鬼神之意告於人之象。史巫皆尚口而巽故也。四巽離為絲，二五升降，史巫紛若，則卑巽之意達於上下，巽在床下，何咎之有？此子游重服，立諸臣之位，以感悟文子之道也。二五，中也，九五未應，則巽在床下，用史巫紛若，乃為得中。九三，頻巽，吝。象曰：頻巽之吝，志窮也。頻水厓與復九三頻復之頻同。兌，水澤。三，水澤之際。九三重剛不中，在下體之上，巽極而決躁，不能巽者也。將遂其剛亢歟，則上臨之以巽，四以柔相親，九二之剛近而不相得。將變而為柔歟，則安其所處，憚於改過，有吝之意。然志已窮，不得已而巽，猶人行至於水之厓，欲前得乎？故曰頻巽之吝，志窮也。易傳曰：雖欲不巽，得乎哉！六四，悔亡，田獲三品。象曰：田獲三品，有功也。四無應，乘承皆剛，宜有悔。四本遁之六二，自二之四，一變訟，二變巽，二田也。艮為手，柔道上行，之四得位，處二陽之際，上巽於五，下巽於三，三爻皆正而相得，故田獲三品。古之田者，上殺、中殺、下殺。為三品，三品則徧及於上下兌有刑殺之意，而又伏艮為黔喙之屬。巽為雞，離為雉，為三品，以巽事上臨下，上下與之巽而有功，雖無應也，乘承皆剛也，其悔亡矣，故曰有功也。易傳曰：天下之事，苟善處則悔，可以有功矣。</p><p>九五，貞吉，悔亡，無不利，無初有終，先庚三日，後庚三日，吉。象曰：九五之吉，位正中也。</p><p>九五君位而正中，巽為號令，有申命之象，故舉全卦以盡一爻之義。五無應，宜有悔正，故悔亡。動則二應之，二五皆正，故無不利。初二不正，始未善也，五正善而有終也。無初故申命，申命則有終，初未善也，故巽以命之。先庚三日，變家人變益之時也。下三爻震，震納庚，離為日先，於此庚之使善也。後庚三日，變噬嗑變震之時也。震納庚，離為日後，於此庚之，慮其未盡善也。先庚後庚，主於中正也。十日之次，以戊已為中，過中則變，故庚謂之更。更而正中正則吉，此九五之所以吉歟？蠱卦六五柔，故為蠱。巽九五剛，乃有更變之善。更天下之弊，其唯剛中乎！</p><p>上九，巽在床下，喪其資斧，貞兇。象曰：巽在床下，上窮也；喪其資斧，正乎兇也。</p><p>上九以巽而居高位，處之不當，窮則變而反下。三以重剛乘之，巽股變艮手，有恐懼自失而蒲伏於床下之象，故曰巽在床下。離兌為蠃，具為資，所以利也。離為兵，巽為木，貫之為斧，所以斷也。上窮反三，離兌巽毀，故曰喪其資斧。喪其所以利，則莫或愛之。喪其所以斷，則莫或畏之，正乎兇矣。上覆位遇坎險，正凶也。魯自襄公三家分其民，其君四世從之，至昭公失國，無所竄伏。蓋處上極巽，盡亡其資斧，乃正凶也。方自失之初，告之以兇，詎肯信乎䷹ 兌下，兌上。 兌，亨利貞。彖曰：兌，說也，剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞，說以犯難，民忘其死。說之大，民勸矣哉。</p><p>兌以一陰居二陽之上，陰說於陽而見乎外者也。兌，巽之反，初六之上，六四之三，柔說於外，二五不失其中，以說行剛，而剛柔皆亨，故曰兌亨。彖曰：兌，說也。此合兩體卦變而言兌也。剛中則實，柔外則接物以和，說而正，則和而不流。卦九五剛中而正，九二剛中，而又戒之以利貞者，二、三、四不正，不正則陷於邪謟，悔吝將至，故說道利正，非道求說不利也，亦何由亨哉？故曰剛中而柔外，說以利貞。此以兩體六爻言兌也。乾，天也；上五，天位也。坤，順也。初六之上而說，順乎天也。三四，人位也。六四、九三相易而說，應乎人也。天人殊位，順乎天者，而在於應乎人而巳。天之說萬物，陰陽相說，降而為澤，說之非其時，則亦不能說矣。湯武之徵伐，出其民於水火之中，而民大說，是所以順天也。知人則知天，知天則知說之道。故曰順乎天而應乎人。此以上六六三兩爻而言兌也。坤為眾民也。坎為勞。兌決。坎為大川。險難也。坤為死。以內卦言。兌先於坤。說以先民也。坤眾從之。兌見坎伏、民忘其勞也。以外卦言之。巽股而涉大川之險。坤化為兌、民忘其死也。夫就佚辭勞，好生惡死，民之常情。用之以說，乃忘四體之勤，決一旦之命而不顧，非說之以道，能如是乎？古之人有行之者，周公之東征是也。故曰：說以先民，民忘其勞；說以犯難，民忘其死。民和則氣和，氣和則天地之和應。說之大，天地不能違，而況於民乎？故曰民勸矣哉。此再合兩體，兼伏爻而言兌也。在卦氣為秋分，故太玄準之以沈。</p><p>象曰：麗澤，兌，君子以朋友講習。</p><p>麗，連比也。澤水所鍾，兩澤相麗，重說也，說之大者也。天下之可說而無𭣧者，無若朋友講習之為大也。易傳曰：兩澤相麗，玄有滋益。朋友講習，玄相益也。兌與兌同，類為朋初，上五始終以正相助為友，兌為口為講，兩兌為習。九五初九之君子，以朋友講其所知，習其所行，相滋相益，體麗澤之象。初九，和兌，吉。象曰：和兌之吉，行未疑也。</p><p>初九剛而處說，無偏系之私，能可否相濟者也，故曰和兌。九四疾惡六三小人，然體巽不果。不果，疑也。初九動而上行，以濟其決，而巽毀九四相易，六亦得位而正，正則吉，故曰和兌吉。初九遠於六三，無嫌於說。小人九四未疑也，是以能濟其決否，則四疑矣。晉訾祐實直而博。範宣子朝夕顧之以問國事，不正其身，未有能決人之疑者，故曰和兌之吉，行未疑也。</p><p>九二，孚兌吉，悔亡。象曰：孚兌之吉，信志也。</p><p>六三小人非道來說，九二比之以陽說陰宜，有悔且兇。九二誠實自信於中，動則九五應之，信孚於人久矣。雖比於小人，和而不同矣，何疑於相比哉？始雖未孚，終必相說，二動而正，正則吉而悔亡，故曰孚兌之吉，信志也。夫石碏、石厚，父子也，叔向、叔魚，兄弟也，子產、伯有，同族也，雖比也，豈能說之？易傳曰志存誠信，豈至說小人而自失乎？</p><p>六三，來兌，兇。象曰：來兌之兇，位不當也。</p><p>兌，巽之反。初。二三皆自外來，柔不當位而乘剛來說於二，說之不以道者也，故曰來兌。三，高位也。柔邪而說，高位兇矣，故曰來兌，兇。楚費無忘，漢息夫躬，唐伾文乎！</p><p>九四，摘兌未寧，介疾有喜。象曰：九四之喜，有慶也。離兌為羸，具貨財也。四動離為震，噬嗑為市之象。巽變之，其於市也，為利三倍，摘賈之象。摘賈度利而動，故又為摘度之象。動承坎，坎，勞卦，勞未寧也。摘兌未寧者，擬議所從，度利而未定者乎。介者，陽剛介於三五之間也。從五，正也。從三，不正也。陰陽失位為疾。九四陽失位，六二陰失位。九四以君子疾小人，六三以小人疾君子。九四宜有憂矣而有喜。九五陽得位為喜，四疾六三不與之交，動而正上從於五，則君臣相說而有喜矣。夫唐、虞、文、武之際，得人為盛，而四族、三叔未嘗，不疾君子，然不害為治者，從君子而不從小人，可不慎其所從乎！易傳曰：若剛介守正，疾遠邪惡，將得君行道，福慶及物，為有喜也。若四者得失未有定，系所從耳。</p><p>九五，孚於剝，有厲。象曰：孚於剝，位正當也。</p><p>陰，消陽也。六三在下，進而上則四五消，有剝床之象，故六三謂之剝。九五正天位，有剛健中正之德當乎位，位與德非不足也，然孚於六三之小人，則九五危矣。六三取說而巳，無獻可替否之義，小人道長，則君子之道曰消，安得不危！易傳曰：巧言令色孔壬，舜且畏之，其可忽諸！</p><p>上六，引兌。象曰：上六引兌，未光也。</p><p>上說道之成，六正巳輔九五剛健中正之君，宜有膏澤下於民而未光，何也？以引六三之小人也。三巽為繩，離為光，上六之說，三相引之，如舉繩然，為山一簣之虧也。此所以未光。歟六三，兌之小人也。故初九剛正者，不疑於三而行也。九二剛中，不比於三也而悔士。九四以三為疾，九五孚於三而厲，上六引三而一未光，小人以說進而為害，其可不慮乎䷺ 坎下，巽上。 渙，亨，王假有廟，利涉大川，利貞。彖曰：</p><p>渙，亨，剛來而不窮，柔得位乎外而上同。五假有廟，王乃在中也。利涉大川，乘木有功也。</p><p>渙，否九四之變也。險難離散，否塞解釋，剛柔皆亨，故曰渙亨。此以卦變言乎渙也。九二之剛，自四而來，動於險中，二陰不能陷，解難散險，又處之以中者也，險豈能窮之哉。五得中道，出乎險外，六四之柔，自二而往，正位乎外，而以巽順上同於五，君臣恊比，能守其中者也。天下之難，患處之者不以道，及其出險，又或不以道守之，則亂者不解，解者復亂。二五之剛，四之柔，處之守之，皆不失中，故曰剛來而不窮，柔得位乎外而上同。此以二、四、五、三爻言渙之才，所以致亨也。天下離散，不安其居者，夲於人心失中，鬼神依人而行，離散則鬼神不饗。聖人推原其本，將以聚之，故建國設官以為民極，而宗廟為先。宗廟者，收其心之渙散而存之也。人孰不有父母，知報本則知祭祀出於人心，復其本心，則離散者可合，而天下無事矣，治渙之道也。假，至也，謂五也。上為宗廟，艮為門闕。五，王位。中者心之位，九五有入於門闕至宗廟，得人心而存之之象。易傳曰：卦之才皆主於中，王者極渙之道，在得其中而巳，故曰王假有廟，王乃在中也。此再以九五而言。渙之才也。利貞者，五也。坎為大川，巽為木，為股，據正體，巽，四二皆為我用，以之濟難，而功歸於五。言乘木有功，則利貞在其中矣。合天下之離散，非正其可乎？故曰利涉大川，利貞。彖曰：乘木有功也。此再以九五、二四吉，渙之才也。易言木者，三益、渙、中孚，存五行也。在卦氣為六月，故太玄準之以文。</p><p>象曰：風行水上，渙，先王以享於帝，立廟。</p><p>風行水上，渙然離散之象。離散之時，天下之險難方作，先王以是享於上帝，以一天下之心，使知無二主也。立廟以合天下之渙散，則人知反本，鬼有所歸。享於帝立廟，離散者一矣。帝，乾上九也。上又為宗廟。巽股為立，坤為牛，坎為血，享於帝也。觀此則知魯用郊晉祀，夏郊，魯有周廟，鄭有厲王之廟，非先王意也。秦位在藩臣，臚於郊祀，天子不能制，反致文武胙，卒並天下。楊雄曰：僭莫僭於祭，祭莫重於地，地莫重於天。雄其知渙之說矣。</p><p>初六，用拯馬壯，吉。象曰：初六之吉，順也。</p><p>虞翻、陸震本作壯吉，悔亡。拯，古本作拯，音承，舉也。六四得位近君，正而巽，可以濟渙，然莫或助之。初欲拯四才柔位下而在坎中，且四不相應，乃舍四用二，用二乃所以拯四也。二剛中之才，坎為美脊之馬，初二相易成震，震為作足，馬美脊而作足，馬之壯健者也。四艮為手，震為起，起手以承六四，拯之象易，則足以資六四之剛而載其上矣，故曰用拯馬壯，吉。正則吉而悔亡。初六處不當位，本有悔也。六坤柔順以陰求陽始渙而拯之，亦順也。故曰初六之吉，順也。五爻皆言渙，初獨不言。易傳曰：渙離之勢，辨之宜早，方渙而拯之，不至於渙也。</p><p>九二，渙奔其機，悔亡。象曰：渙奔其機，得願也。四巽為木，坎為揉，震為足，艮為手，在上體為肱。揉木令曲而有足，肱據其上，機也。二四合乃有此象。二有剛中之才，處險而不當位，宜有悔，二能奮身出險，上奔於四，四來憑之以安，機憑之以安者也，是以悔亡。震足動，奔也，故曰奔其機。二本否四，在二者渙散之時也。二之情不忘乎四，猶逃空之人不忘故國。奔則得中心之所欲，二中者心之位也，故曰得願也。</p><p>六三，渙其躬，無悔。象曰：渙其躬，志在外也。</p><p>所以致渙者，險在內也。四五濟險之位，六三處不當位，近險宜有悔。然不與險爭，動而之上，自脫於險，非拯時之渙以濟人者也，其正躬卑巽以遠於悔者乎！坤為身，三上相易，折坤成巽，離目視下，鞠躬之象，故曰渙其躬，無悔。象曰：志在外也。之外則無悔，三上合而得正也。蘧伯玉聞衛亂而之近，關杜洩葬叔孫豹而行之時乎？</p><p>六四，渙其群，元吉。渙有丘，匪夷所思。象曰：渙其群，元吉，光大也。</p><p>坤為眾，渙三陰群也。四巽順而正，居近君之位，上以巽乎五，下以巽乎二，二剛中有濟，渙之才，而二陰比之。四屈己濟難，與眾同患，得九二之助，陰服矣。則散者合，異者同，共圖天下之渙，是以元吉。元吉則濟渙之志光且大矣。坎為光，陽為大也。渙之時，用剛則不足以懷之，用柔則不足以制之。四二協力，剛柔共濟，渙而至於群，天下始可以聚矣。五艮為山，半山為丘。丘，聚也。六四得九二以合其群，其心思之所存者在五。五得位，群陰之所聚，如物之聚於丘。五中正善群，然非四合之，亦不得而群矣。四視二陰，等，夷也。四正初與三不正。坤土，思也。所思匪若二陰之所思不正，故九二為用，二陰服之，否則渙散矣，其能效美於君有丘之實乎？故曰渙有丘，匪夷所思。宣王承厲王之後，天下離散，召伯之徒佐王建國親諸侯，遣使勞來安集，渙其群也。</p><p>九五，渙汗其大號，渙王居，無咎。象曰：王居無咎，正位也。有疾者，閉塞不通，陽降陰升，浹於腠理，否者亨矣。否乾降二，坤陰升四，降者成坎，坎水浹於上下，汗出之象，號令如之。巽為號，陽為太，九五出號令者也。故曰渙汗其大號。五至三體升，有風行地上，省方設教之象。能發新命以順民，上下交通，險難解釋，渙汗其大號也。渙時民思其主、故王居正位乃無咎。在他時安居不能順動、則有咎矣。故禹別九州而終於冀、湯勝夏而歸於亳、武勝商而至於豐。王正位、則渙散者知所歸矣。乾五為王、艮為居止也。得正則無咎。然九五非六四之賢、與上同志、安能發大號居其所而治哉！易傳曰：再言渙者，上為渙之時，下處渙如此為無咎。</p><p>上九，渙其血，去逖出，無咎。象曰：渙其血，遠，害也。</p><p>先儒讀渙其血作一句，去逖出作一句，以象考之，當從先儒。九二，坎乾為血，血者相傷之象。渙五爻不應，上九獨應六三，六三近險，見傷，上九下應之。三上相易，上覆成坎而傷，故曰渙其血。言上三俱傷也。上九能去六三，遠出乎險之外，自處以巽，不陷於險，則是去而遠害，於義無咎。逖，遠也。故曰渙其血，去逖出，無咎。一本作去惕出。巽為多白眼，有惕懼之象。然象曰遠害，當從逖矣。渙時以合渙為功，上九居不用之地，故遠害無咎。繫於六三而不去其傷，自取也。若施之用事之地，則有咎。仲由死於衛，季羔避禍而去，一也。䷻ 兌下，坎上。 節，亨，苦節不可貞。彖曰：節亨，剛柔分而剛得中，苦節不可貞，其道窮也。說以行險，當位以節，中正以通，天地節而四時成。節以制度，不傷財，不害民。</p><p>節，渙之反，泰之變也。泰分九三之五以節其上之柔，分六五之三以節其下之剛。剛柔分而有節，二五之剛得中，上下節之而不過。所謂節者，剛柔有節而不過乎中，不過則亨，故曰節，亨。剛柔分而剛得中，不曰柔得中者，剛得中則柔不過矣。此以卦變二、三、五爻言節之所以亨也。上六乘剛處險，守而不變，所以不可貞者，節之道窮也。易窮則變，變則通，通則久，守而不變，苦節也。凡物過則苦，味之過正，形之過勞，心之過思，皆曰苦。苦節，則違情性之正，物不能堪，豈道也哉。申屠狄之潔，陳仲子之廉，非不正也，立節太苦，不可貞也。夫節者，為其過於中也，故節之使不失其中。上六正而過矣，安能節乎？故曰：道之不行也，我知之矣。賢者過之，不肖者不及也。自不肖觀之，過者為賢；自中言之，過不及一也。謂之正者，貴乎中正也。正而失中，不可正也。故曰苦節不可貞，其道窮也。此以上六無應，戒苦節也。兌，說也。坎，險也。人情易則行，險則止。凡止而行，皆有險之道，節止而不行者也。泰之九三，上行自兌成坎，以說行險也。以說行險，雖止不失其和矣。和而不流，中立而不倚，故曰說以行險。此以九五言節之亨也。九五，節之位也。中正，節之道也。當位以中正為上下之節，各適其宜，無所不行，故曰當位以節，中正以通。此以九五言節亨者，當有位也。九三一變歸姝，震為春，離為夏，節之以春夏也。再變節兌為秋。坎為冬。節之以秋冬也。天地有節、則陰陽寒暑不過、而萬物成於艮。故曰天地節而四時成。離兌為貝。貝為財。乾為金玉。坤為民。泰甚則人慾縱。人慾縱則財用匱乏、百姓困窮。故量財之所入、計民之所用。節以制度，自下等級而上，其費有經，其斂有法，財既不傷，民亦不害。是以天地不節，則四時不成，王者不節，則民財不生，無非節亨也。故曰節以制度，不傷財，不害民。此又推原卦變玄體，以盡節之義也。在卦氣為七月，故太玄準之以度。象曰：澤上有水，節，君子以制數度，議德行。</p><p>澤之容水，固有限量，虛則納之，滿則洩之，水以澤為節也。君子於民亦然，制其多寡，制其隆殺，制數度也。制數度者，坎之象也。律度量衡，皆始於黃鐘，冬至之律，於辰為子，於卦為坎，九五以中正為節也。乾為德，震為行，兌口為議，議德行者，恐其中而未正也。易傳曰：議謂商度，求中節也。</p><p>初九，不出戶庭，無咎。象曰：不出戶庭，知通塞也。</p><p>初九，六四正應也。往來相易不窮，故曰通。九二近而不相得，窒其所行，故曰塞。初九，兌體剛決，動成坎，坎水為知，故知通塞。五艮為門闕，交兌為戶。四在門闕之中為庭。不出者，自守以正而已。動有險，故不出戶庭。乃無咎。不出則處也。在言語則默亦是也。不出而處，不語而默，雖有正應，不說也。是之謂節。兌為口舌，故繫辭專以慎密不出言之。易傳曰：通則行，塞則止，義當出則出矣。君子貞而不諒。或曰：艮為門闕，又曰交兌為戶，何也？曰：兌為戶，震為門，艮土在啟閉之際，故為門闕。乾始於子，至醜直艮，至寅成泰。泰者，天地交通，至夘直震，故震交艮為門。震即乾之闢戶也。是以雷發聲，蟄蟲開戶。坤始於午，至未直坤，至申成否。否者，天地閉塞，至酉直兌，故兌。交艮為戶，兌即坤之闔戶也，是以雷收聲，蟄蟲壞戶。</p><p>九二，不出門庭，兇。象曰：不出門庭，失時極也。</p><p>極，至中也。二動歷四，應五成震，震為門，四在門闕之中為庭，二以中應五之中極也。當其可之謂時，故曰時極。時極者，時中也。九五剛中當位，酌民情以為節。九二有剛中之德，動而應以趨節之時，則中正之節達於下矣，得時極也。若說於三，陰與五異，趨固而不知變，門庭可出而不出，是得時極而自失之也，所以兇者，其節不正也，故聖人戒之。六三，不節若，則嗟若，無咎。象曰：不節之嗟，又誰咎也？六三柔不當位，說而失中，不能節之以剛者也。有子曰：知和而和，不以禮節之，亦不可行也。三不能節，則乘剛失位，以說從人而巳不能堪焉，故憂發於口，諮嗟而巳。三變而剛，剛不失節而上自應，夫何憂哉！易傳曰：節可以免過，而不能自節以致可嗟，將誰咎乎？此爻與離之九三不鼓缶而歌，則大耋之嗟兇，象累而意同。</p><p>六四，安節，亨。象曰：安節之亨，承上道也。</p><p>節，止也。凡止物有險之道，險非人情之所安。上三爻皆處險，六四當位履正，安於處險，以順承上而止物焉，安於節也。六四能安於節者，以承上中正之道，以此節下，下必應之節，道行乎上下而亨，亨則通矣，非中正豈能安其節哉！易傳曰：節以安為善，強守而不安，則不能常，豈能亨也？</p><p>九五，甘節，吉，往有尚。象曰：甘節之吉，居位中也。</p><p>節者，理之不可得而過者也。九五居位，以中為制節之主，安行於上而不動，甘節也。五自泰九三變以說行險，有甘之意。先王建國宅中，均道里，制邦域之時乎正則吉，二說從之，往有尚也。尚，配也，往有配乎中也。詩曰：商邑翼翼，四方之極，往有尚也，故九二不出門庭，兇。彖言當位以節，中正以通，爻止言居位中，何也？彖言九五一爻，此言九五、九二相易也。易傳曰：巳則安行，天下則說從，節之至善者也。</p><p>上六，苦節，貞兇，悔亡。象曰：苦節貞兇，其道窮也。</p><p>節過乎中，居險之極，人所不堪，下無說而應之者，苦節也，不可貞，貞則兇，其道窮也。上九固守乎正，不知俯而就中，則悔亡。五，中也。悔則窮，能悔則亡，兇矣。易傳曰：悔亡，損過從中之謂也。節之悔亡，與他卦之悔亡，辭同而意異䷼ 兌下，巽上。 中孚，豚魚吉，利涉大川，利貞。彖曰：</p><p>中孚，柔在內而剛得中，說而巽，孚乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。中孚自遁來，訟之變也。二五不應，六三孚於上，六四孚於下，二爻在中而孚中孚也。易傳曰：中孚者，信之本；中實者，信之質。夫信之未彰無形矣，其中巳有信也，非中虛乎？靜而正，發而當，反諸已而不怍，斷然如金石之不可易，非中實乎？故曰：柔在內而剛得中。此以三、四、二、五言中孚也。上巽施之，下說從之，巽說相與，不期於孚而孚焉，猶鳥之孚卵也。巽伏於上，說從於下，不動而柔者化，剛者應，拚然而飛矣。化邦之道，不幾於是乎。坤在上為邦國，外巽內說，感之以誠信，久而自化，不為而成也。其象巽離化坤，巽離者，萬物化成之時，故曰說而巽，孚乃化邦也。此總六爻而言中孚也。豚魚，六四也。中孚六四，即訟坎之初。坎為豕，其初為豚。三兌為澤，四巽乎澤為魚。六四一爻具豚魚之象，而在中孚之中，信及豚魚也。先王之交萬物，無非信也。取之必有時，用之必有節。風有騶虞，信及豚也。頌有潛，信及魚也。動物之蕃息者，莫如豚魚。信及豚魚，上下草木鳥獸無所不及，而至誠之道，可以贊天地之化育，如是乃吉。六四，正也，正則吉信，至於賞罰而示之者末矣，非心服也，其終必兇，故曰豚魚吉。彖曰：信及豚魚也。此以六四言中孚也。坎為險難，初越二三，涉坎成巽，巽為股，涉，大川也。兌澤而為大川，決而成川也。巽為木兌金刳其中，舟虛也。舟虛者，中虛之象。九五體巽其中虛，不以好惡之私累其心，其下說而不違，利以濟難也。夫乘木之利，乘桴不如乘舟，重載而乘險者，不如虛舟之為安。仗誠信而蹈大難，猶乘木而其中枵然，豈復有風波之虞哉？古之人虛巳遊世，五兵兕虎不能害，用此道也。故曰利涉大川，乘木舟虛也。此以四五言中孚之功也。天之道不言而善信，四時自成，萬物自生，正而巳矣。正，誠也。六四之正，乃應乎天者，以其心正，其心正則其意誠，乃應於天之道，非人為也，故曰中孚以利貞，乃應乎天也。此以六四、初九相應，言中孚也。初九本九四，乾在上，為天之象，在卦氣為冬至，故太玄準之以中。</p><p>象曰：澤上有風，中孚，君子以議獄緩死。</p><p>澤上有風，澤中應之，中孚也，中乎信也。中孚自訟，變坎為獄，九四之初坎成兌，兌為口，議獄也。議獄者，議其獄情之正否也。艮六變成中孚，艮體盡矣，為遊魂，遊魂，死之象。震為反生緩死也，緩死者，未必死也。君子議獄緩死，則好生之德孚於上下矣。傳曰：冬至四十五日條風至，出輕刑，解稽留。法此象乎？</p><p>初九虞吉，有它不燕。象曰：初九虞吉，志未變也。</p><p>中孚之初，戒在審慎其所信。初九、六四，正應也。初宜信四，而初四相易，以失位為憂，以其有憂也，故虞度之。虞乃不失其正應，故吉。虞度而得其所從宜，誠一不貳，有它則擇利而動，心無所主，惑矣。燕謂三也。雷在澤中，有燕息之象。三非初之正應，初與三同體，說乎陰而往應之，為有它初之三，歸妹象。毀而不燕，以其貳也。初九所以虞吉者，得其所從，其志未變於三，變於三矣，何燕之有？</p><p>九二，嗚鶴在陰，其子和之。我有好爵，吾與爾靡之。象曰：其子和之，中心願也。</p><p>訟離為飛烏，變震為鶴。說卦震為鵠。鵠，古鶴字也。穆天子傳、列子皆以鵠為鶴。鶴震聲，感兌鳴於正秋，九二之象也。九二剛實而中，中孚之至者。九居二，鳴鶴在陰也。坤為母，巽四為子。四與二同體震，而九二陽為大，六四陰為小，故四有子之象。二四志同，二鳴而四和，二，中也。四亦中虛心之象，其應豈強為哉。出幹中心願而巳矣。荀子所謂同焉者合，類焉者應，故曰其子和之，中心願也。巽為命，五出命者也。陽為美好，好爵者，爵命之美。吾四自謂也。我四謂五，猶曰我君也，爾親乎二也。二誠於中，四自和之，若曰我君有好爵，吾與爾共靡之，非二有求於四也。四於五，其疏附之臣乎？靡，子夏傳陸績作縻，巽為繩，縻繫之象，當作縻。孟子曰：我善養吾浩然之氣。莊子曰：吾無食，我無糧。古人文章相錯而成，此爻所謂我吾亦然。易傳曰：至誠無遠近幽深之間，唯知道者識之。</p><p>六三，得敵，或鼓或罷，或泣或歌。象曰：或鼓或罷，位不當也。</p><p>敵者，勢均而不相下也。艮之彖曰：上下敵應，不相與也。言六爻勢均，當應而否。故子夏傳曰：三與四為敵。蓋三四同體而異意，近而不相得。六三不正，小人也。六四正，君子也。三小人不見信於君子，而志在得四。四終不可得。震為鼓。三動鼓而進、將以張之也，而四不應。既罷而退、將以誘之也，而四不來。三動離為目、兌澤流目、或泣以感之、而四不憂。巽為長。震為聲。兌口為言。長聲以永其言。或歌以樂之，而四不悅。或鼓或罷、或泣或歌、小人之情狀盡矣。四守正，終莫得之，處位不當，無以取信於君子也，豈能強得之哉！</p><p>六四，月幾望，馬匹亡，無咎。象曰：馬匹亡，絕類上也。四處當位近君，其道上行，成孚者也。訟，離為日，坎為月，坎變震，月在東也；離變兌，日在西也。月東日西，望也。五在中，四為幾望，陰道之盛，盛則敵君，禍敗必至，不可不戒。古者駕車四馬，兩服為匹，兩驂為匹。不能四馬，則駕兩馬，曰駢。駢亦匹也。四震為作足馬，四應初成坎，坎為美脊之馬。兩馬匹也。震坎陽卦，類也。四之上絕其類而不應，則馬匹亡矣。孚道在一，四上從五，亡其匹則絕系應之私，無敵君之禍。易傳曰：系初則不進，其能成孚乎？</p><p>九五，有孚攣如，無咎。象曰：有孚攣如，位正當也。</p><p>九五在上，六四在下，君臣之位正也。九五剛健中正，六四柔巽正而順，君臣之德當乎位也。五四君臣相孚，上下固結，如攣然，相易以致用，故無咎。攣，拘攣也。五四相易，有巽股艮手、離目相就拘攣之象。夫忠為令德，苟非其人不可。君臣之際，非位正德當，其孚如是，豈能無咎乎！</p><p>上九，翰音登於天，貞兇。象曰：翰音登於天，何可長也！巽為雞，剛其翰也，柔其毛也。翰，羽翮也。震為聲，上動反三成兌，雞振其羽翮而後聲出於口。翰，音也。乾五為天，六三往上陰為虛，翰音登於天也。鳥之類聲聞於天者，鶴也。雞無是實，虛聲聞於上，雖登於天，湏臾則反，其可長乎。巽為長，三之上巽毀，何可長也。不信之極，正乎其兇，故曰貞兇。張載曰：信之無實，窮上必兇。䷽ 艮下，震上。 小過，亨利貞。可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。彖曰：小過，小者過而亨也。過以利貞，與時行也。柔得中，是以小事吉也。剛失位而不中，是以不可大事也。有飛鳥之象焉，飛鳥遺之音，不宜上宜下，大吉，上逆而下順也。</p><p>小過與中孚相易，其卦四陰二陽。陽為大，陰為小。小者，過也。六五過四而亨於外，六二過三而亨於內。蓋事有失之於偏，矯其失，必待小有所過，然後偏者反於中。謂之過者，比之常理則過也。過反於中，則其用不窮而亨矣。故曰小過亨。彖曰：小者，過而亨也。此以四陰之中舉六二、六五言小過也。小過自臨來，明夷變也。臨九二之三、六三之二成明夷，二過乎三也。明夷初九之四成小過，五過乎四也。二過乎三，正也。五過乎四，不正也。不正者，矯其失而過正也。正者，時所當過，過所以就正也。所謂時者，臨之兌，秋也；震，春也；明夷之離，夏也；坎，冬也；小過之艮，終始也。過與時行，而六二之正不動。於六二不動，乃能小過而亨，利貞也。君子制事以天下之正理，所以小過者，時而巳。譬之寒或過於陰，暑或過於陽，冬裘夏葛，無非正也，故曰過以利貞，與時行也。此以六二言小過也。二五之柔，皆得中也。五得中得尊位，過而在上者也。二得中得正，過而在下者也。巽為事正則吉。小過之道，不以位之上下，於小事有過而不失其正，則吉，柔得中也。九四剛失位，九三剛而不中，震為作，陽為大。作大事非剛得位、得中不能濟。失位則無所用其剛。不中則才過乎剛。是以小過之時、不可以作大事。故曰小事吉、不可作大事。此以二三四五言小過也。明夷離為鳥。初往之四、自下而升、有飛鳥之象。四易坤成坤震。震為聲。聲往於上而止於下，飛鳥遺音之象。巽為風，飛鳥遺之音。逆而上則難，順而下則易。上逆也，故不宜上。下順也，故宜下。小過之時，事有時而當過，所以從宜，不可過越已甚，然亦豈能過哉。譬如飛鳥溯風，決起而上騰，其音安能遠過俄頃而止矣。大者如是則吉，不然必兇，時不可犯也。故曰有飛鳥之象焉。飛烏遺之音，不宜上宜下，大吉。此復以初九之四言小過也。中孚肖乾，小過肖坤，故二卦為下篇之正。鄭康成曰：中孚為陽，貞於十一月子。小過為陰，貞於六月未。法於乾坤。以卦氣言之為立春，故太玄準之以差。</p><p>象曰：山上有雷，小過。君子以行過乎恭，喪過乎哀，用過乎儉。</p><p>雷出地上，其壯乘乾。山上有雷，小有所過也。君子有時而小有所過者三。巽乎上下而過，行過乎恭也。震巽為號啕，而上六過之，喪過乎哀也。巽為高，坤為吝嗇。處高而吝嗇，逼下巳甚矣。初六過之用，過乎儉也。時當小過，君子不得不小有所過，以矯正一時之過。考父之過恭，高柴之過哀，晏平仲之過儉，非過於理也，小過乃所以為時中也。</p><p>初六，飛烏以兇。象曰：飛烏以兇，不可如何也。</p><p>明夷離為烏，初之四，飛烏也，以如師能左右之曰以。四動體而躁，初，艮體不正，柔而止，不當過也。有應在四，為四，所以不當過而過，其過至甚，如飛烏迅疾，雖欲救止，不可如何，其兇必矣。坎為可，四以之坎毀不可也。兌口如何也，與鼎信如何也同象。是謂惡成而不及改者。易傳曰：小人躁易而上應助過速且遠，不容救止也。</p><p>六二，過其祖，遇其妣，不及其君，遇其臣，無咎。象曰：不及其君，臣不可過也。</p><p>三乾在上為父，四為祖。五坤陰居尊位，配乎祖妣也。曰祖曰妣，既，過之稱。六二中正，祖，尊也，妣亦尊也。祖不中正，於義當過。妣，中而過之，義不可也。過則失中矣，故遇之。遇不期而會，五不應二，以中相會，故遇之。言過而適與中相當也。五，君之位，坤居之。坤，臣也。過而適及於臣之分則可。過而及於君，過臣之分也，於義為有咎，故不可不戒。易傳曰：遇，當也。過臣之分，其咎可知。</p><p>九三，弗過防之，從或戕之，兇。象曰：從或戕之，兇如何也。九三剛正而應上六，應則過五。五，中也，中不可過，三戒在小，不忍用剛以過中，故弗過。宜，正己自守，防小人則吉。兌澤坤土，止之防也。三不防，乃舍所守從之，剛過乎中，上或戕害之矣。離為戈兵，巳動失正，戕之也。戕者，外傷之如何？兌口也，與初六如何同象。不能守正，見戕於外，其兇果如何也。晉陽處父易狐射姑之班，伯宗言於朝，而諸大夫莫若，皆過之而弗防，改及於難。</p><p>九四，無咎，弗過遇之，往厲必戒，勿用永貞。象曰：弗過遇之，位不當也。往厲必戒，終不可長也。</p><p>四不當位，以剛履柔，為得宜矣，故無咎。四下應初則過二，二，中也，弗可過也。知二不可過，乃與五遇，五亦中也，弗過二則與中適相當，遇得其道矣。若去柔用剛，進而之五，往則危厲，故必以用剛為戒。往之五成離，戈兵之象，不動兌為口戒也。小人過君子之時，不戒而用剛，鮮不為禍。故丁寧之既曰必戒，又曰勿用永貞。當隨時處順，不可固守其正，是以終無咎也。然盛衰相循，無小人常過君子之理。巽為長。陸震曰：小者之過，終不可長也。戒而慎之，以俟其復。</p><p>六五密雲：不雨，自我西郊，公弋取彼在穴。象曰：密雲不雨，已上也。</p><p>兌澤之氣上而為雲，兌，盛陰也，故為密雲。澤降為雨。小過自明夷變初九，往四成兌，澤氣已上而未降，雲雖密而無雨，故曰密雲不雨，已上也。言陰過陽，君子之澤未能下也。四在內外之交而見天際，郊之象。四，兌西也。五，震東也。巽風揚之雲，自西往東，由陰而升，陰唱則陽不和，不雨之象，故曰自我西郊。三公位。明夷三坎為弓，離為矢。初之四成巽，巽離為絲，以絲系矢，弋也。弋取之器也。坎兌為穴，坎，幽隱也。艮為手，取也。彼謂二，六二在穴中，有中正之德，處於幽隱。九三君子俯而取之，往助於五。然六二六五同為陰類。三雖取之，豈能濟大事乎。小過之時，柔得尊位，二陽在下，為陰所過，不能成功。三下取二，用力多矣，亦豈能濟哉。謂四陽為我，二陰為彼，以陽為主也。若中孚陽謂陽，則謂五曰我，自謂曰吾，謂二曰爾，尊卑之義。小畜彖曰：密雲不雨，尚往也；自我西郊，施未行也。其辭與小過六五同。蓋小畜所畜者小，小過則所過者小，皆不可以作大事，過之則畜之矣。二卦雖殊，而大者為小者所畜，而不得施則一也，故關子明曰：小畜一卦之體，當小過一爻之義。然則畜之一也，小大之時異焉。</p><p>上六，弗遇過之，飛烏離之，兇，是謂災眚。象曰：弗遇過之，巳亢也。</p><p>上六不與五相當，失中也。又動而過之則甚矣，而況處小過之極，於時為巳亢乎！故曰弗遇過之。上動成離，離為飛烏，為目，巽為繩，以繩為目，罔罟之象，其違理過常，猶烏飛過甚，自離於罔罟，故曰飛烏離之。兇。動則不正，故兇。離有伏坎，災也。弗遇過之，災乃自取，非天也，人也。而曰災眚者，過之極，窮之災也，於時已亢也。人事過越如此，使知時而守正，未必能免已亢故也。䷾ 離下，坎上。 既，濟，亨，小利貞，初吉，終亂。彖曰：既濟，亨，小者亨也。利貞，剛柔正而位當也。初吉，柔得中也。終止則亂，其道窮也。</p><p>既濟自泰來，豐九四變也。泰兌為澤，九二之四成豐，四已濟險，而小者未盡亨，九四之五則小者亨矣。於濟為既，其卦三陰得位，三陽下之，大者既濟，小者亦亨。子夏傳曰：陽巳下陰，萬物既成。不曰小亨，而曰亨小者，大者之濟為亨小者，而濟非為巳也。禹思天下之溺，猶己溺之。稷思天下之飢，猶巳飢之。亨至於小，則小大畢亨，故曰既濟亨。小彖曰：既濟亨，小者亨也。彖文當曰既濟亨小，小者亨也，脫一字。此以三陽下三陰而言既濟也。以陽下陰，非正也，亨之也。剛，君子也；柔，小人也。剛柔不失其正，君子小人各當其位，無犯分躐等之非，守既濟之道也，故曰利貞，剛柔正而位當也。此以六爻當位而言既濟也。自泰至賁，二復三變。始於二之四成豐，次四之五成既，濟其終五之上而成賁。濟天下之難莫若剛，過剛亦不可以濟，失人心也。方濟之初，以柔濟剛，則其柔得中，剛者為用，天下之難有不濟乎。此既濟之初所以吉。正則吉也。既濟矣。上六變艮成賁，艮，止也。止而不進，不復有為，文飾而巳。濟終則極，衰亂復起，終以亂也。蓋其道巳窮，故曰初古終亂。彖曰初吉，柔得中也。終止則亂，其道窮也。終始，時也。治亂者，道之窮通也。晉隋有天下，不旋踵而亂，不知終止，則亂之戒也。易傳曰：唯聖人為能通其變於未窮，不使至於極也，堯舜是也，故有終而無亂。此推原卦變，以九五一爻言既濟之終始也。在卦氣為十月，故太玄準之以成</p><p>象曰：水在火上，既濟，君子以思患而豫防之。</p><p>水火相逮而後濟。天地之道，以坎離相濟。以日言之，曰降則月升，以月言之，日交則月合。以歲言之，寒來則暑往。皆既濟也。坎上離下，既濟矣。然既濟之極，水火將反其初，故既濟之象，未濟藏焉。君子不可不思慮以豫防其患。坤土為思，坎為險。難，患也。土防水防也。在既濟之時而防險難，豫也。思患而豫防之，則難伏而不作。或曰：五動坤變坎成震，體豫而未濟之象毀矣。初九，曳其輪，濡其尾，無咎。象曰：曳其輪，義無咎也。三坎為輪，初卦後為尾。初九剛而離體，炎上有應進於上，其志必銳，時既濟矣，動而進不巳，必至於咎，故戒之。初動之四成艮，艮為手曳也。坎輪在水火爻中，火欲上，水欲下，亦曳也。曳其輪不輕進，尾濡坎水不速濟，止之於初，持重緩進，以全其剛，而不至於極，則於既濟之義為得矣，故曰義無咎也。</p><p>六二，婦喪其茀，勿逐，七日得。象曰：七日得，以中道也。二坤為輿，三坎為輪。二之五離變震，坤離為文，震為竹，竹有文，蔽車之前者，茀也。離為婦，婦人乘車，不露見，有茀乃可以行。五於既濟之時，安其位，無動而有為之意。二雖有文明中正之德，不得遂其行，婦喪其茀也。五坎為美脊之馬，二五相易，震為作足之馬，逐也。五不下二，二當以中道自守，故戒以勿逐。逐則失其素守而不正。七日得自二數之至上為五。復自初數之至二凡七日，以中道也。中道者、天地之所不能違。故坤極生乾，七日必復。而況人乎。易傳曰：自古既濟用人蓋鮮矣。以唐太宗之用言，猶怠於其終，況其下者乎！雖不為上所用，而中正之道無終廢之理，不得行於今，必行於異時。九三，高宗伐鬼方，三年克之，小人勿用。象曰：三年克之，憊也。</p><p>坤為鬼、為方，五坎為險，帝繫有鬼方氏，鬼方蓋國名，小國於既濟之時，恃險不來。九五離體，有戈兵，用九三往伐之。坤為年，自四數之，歷三爻，三之上成巽，巽為入，入其險也。上之三成坤，順也。既入其險，鬼方來順，三年克之也。克，難辭也。九三剛正，君子也。上六之三，柔而不正，小人也。高宗中興之賢君，伐鬼方氏之小國，歷時之久，至於三年而後克之，其力亦憊矣，況用小人乎？坎為勞重，坎憊也。小人非貪慾不為其禍，至於殘民肆欲，遂喪其邦，故戒以小人勿用。爻言勿用小人，象曰：憊者，聖人慮後世勤兵於遠託，高宗久伐以濟其欲，勞民動眾，三年克之，雖高宗行之亦憊也。</p><p>六四，𥜗有衣袽，終日戒。象曰：終日戒，有所疑也。</p><p>四，坎水也。初之四成巽，巽木在水上，舟之象。四未交初，巽毀坎，見舟漏也。四坤為裳，𥜗，裳也。初乾為衣，艮為手。袽，塞也。離日在下，終日也。兌為口，戒也。巽為不果，疑也。六四近君而正，明於防患，資初九之賢，彌縫九五之闕，終日相戒，如奉漏舟，不唯自竭，而初九助之，如有裳及衣，袽塞其漏，苟可以豫防者無不為，斯能濟乎重險矣。制治保邦之道，患至而後慮之，無及己心，有所疑，知禍亂之源，必先事而塞之，乃保既濟之道，故曰終日戒，有所疑也。易傳曰：不言吉者，方免於患也。既濟之時，免患足矣，無復有加矣。</p><p>九五，東鄰殺牛，不如西鄰之礿祭，實受其福。象曰：東鄰殺牛，不如西鄰之時也。實受其福，吉大來也。</p><p>泰震為東，兌為西，三四鄰也。兌為刑殺，坤為牛，坎為血，離為夏，震為聲，上為宗廟，九二之五、有長子奉祀、東鄰殺牛、西鄰礿祭之象。殺牛、盛祭也。礿尚聲、薄祭也。盛不如薄者。時也。二五均有中正之德。然二未濟有進也。九自五來、二以虛受、故曰實受其福。正吉。陽為大吉、大來也。五既濟、無所進也。盈則當虛、故曰不如西鄰之礿祭也。理無極而不反者，既濟極矣，時巳往矣，五以中正守之，能未至於反而巳。易傳曰：至於極，則雖善處無如之何矣。</p><p>上六，濡其首，厲。象曰：濡其首，厲，何可久也。</p><p>上既濟之極，以剛處之，猶恐其反，六安其位而不變，必有顛隕陷溺之患。上反三乾為首，濡於坎水之中，濟而至於水，濡其首，危極矣。濟之窮也，其可長乎？巽為長。易曰：既濟之終，小人處之，其敗可立而須也。䷿ 坎下，離上。 未濟，亨。小狐汔濟，濡其尾，無攸利。彖曰：未濟亨，柔得中也。小狐汔濟，未出中也。濡其尾，無攸利，不續終也。雖不當位，剛柔應也。</p><p>未濟自否來，既，濟之反也。否塞之時，六二之柔得中而上行，天地相交，否者亨矣。柔而不中，則介於二剛，其能亨乎？故曰未濟亨，柔得中也。此以二五言未濟也。艮坎為狐。小狐，初爻也。艮之初爻為小狐，猶中孚之豚。亦初爻也。爾雅曰：𧰙，汔也。詩曰：汔可小康。鄭康成曰：汔，幾也。四為坎險，五為中，出險也。初往之四，幾濟而未及於五，未出中也。狐首輕尾重，老狐聽水，負尾而濟，其剛不息，是以終濟卦以成卦言之，上為首為前，初為尾為後。以畫卦言之，初為始為卒，上為終為末。上九，剛也，初六，柔也。小狐不度而進，未能審慎，其前則剛，其後乃柔。四坎濡其尾，往無攸利，以其剛不足，不續終也。然則濟險者，其在於審慎始終，如一剛健不息者乎？孟喜曰：小狐濟水，未濟一步下其尾，故曰小狐汔濟，未出中也。濡其尾，無攸利，不續終也。此以初六、九四相易，言初六之柔不足以濟險難也。未濟六爻雖不當位，而剛柔相應，苟量力度時，慮善而動，上下內外相與，未有不濟者也。故曰雖不當位，剛柔應也。此以六爻申未濟，有可濟之理也。在卦氣為十一月，故太玄準之以將</p><p>象曰：火在水上，未濟，君子以慎辨物。居方</p><p>未濟，自否變否，艮止也。慎之象，離為明辨也。火，陰物也，居南；水，陽物也，居北。二物有相濟之理。火上水下，各居其所，未濟也。君子觀此，慎辨萬物，使各居其所，有辨然後有交，辨之以正其體，交之以致其用。不辨則不交，有未濟乃有既。濟，而未濟舍既濟之象。</p><p>初六，濡其尾，吝。象曰：濡其尾，亦不知極也。卦後為尾，坎水濡之，濡其尾也。初處險下而上有應，其志欲動，在未濟之時，剛動則出險於濟為得其分量矣。極，分量之極也。初柔，九二又以剛在前阨之，雖有應可動，而柔不能動，吝也。於是而欲濟，是亦不知極也，猶獸慾濟而力柔，水濡其尾則不能舉，終亦不出乎險矣。坎水為知。</p><p>九二，曳其輪，貞吉。象曰：九二貞吉，中以行正也。</p><p>坎為輪，二往五應，艮為手，曳其輪也。坎輪在水火爻之中，水欲下，火欲上，亦曳也。二，中也。九二之五，中以行正也。未濟時，六五柔處尊位，五所賴者。九二剛中也。剛非臣德之正也。剛或好犯，恭順之道或有不足，故戒以曳其輪，則緩進以盡恭順，於臣為中，於道為上。行中以行正者，正未必中，中以行正則盡矣。易傳曰：唐郭子儀、李晟當艱難未濟之時，能保其終吉者，用此道也。</p><p>六三，未濟，徵兇，利涉大川。象曰：未濟徵兇，位不當也。三處險中，唯至剛乃可以出險。六柔不當位，未濟也。以柔而行，外援上九，則乾首沒於坎中，淪胥以溺之象，雖正亦兇，竇武何進是也，故曰徵兇。三四非應，當未濟之時，三資其助，四近而恊力，巽股出險，利涉大川矣。</p><p>九四，貞吉，悔亡。震用伐鬼方，三年有賞於大國。象曰：貞吉悔亡，志行也。</p><p>九居四有悔，動而正，正則吉而悔亡。四動體震，震為威怒，坤為鬼方，坎為險，四近君，剛而明，有濟之道，初恃險未順，四用其威怒以入其阻、伐鬼方也。自三至初歷三爻。坤為年。三年而後順。克之也。克、難辭。艮山坎川、坤土、田賞之象。坤四為國、陽為大。有賞於大國、非貞吉悔亡、其志於上下乎。二卦言伐鬼方者、藉此以明必濟之義。天下之弊、固有盤結而難去者。四凶頑民，歷世既久乃能去之，故曰貞吉悔亡。易傳曰：古之人用力之甚者，伐鬼方也，故以義動而遠伐，至於三年，然後成功而行大國之賞，必如是乃能濟。四居柔，故戒以此。</p><p>六五，貞吉，無悔。君子之光，有孚，吉。象曰：君子之光，其暉吉也。</p><p>六五，文明之主，柔居尊位，悔也。虛中而下九二，二往五正，以剛濟柔，故貞吉無悔。坎為光，君子之光，謂九二也。五離為明，二與五應，光明相燭，有孚也。暉者，光之散。管輅曰：日中為光，朝日為輝，朝日初出，其光輝散也。言二五未交，其德暉之所及巳孚於上下則吉。濟險難者，君必剛正，臣必有不言之信，然後委任篤下，無間言，功，濟天下而無後患，不然，兇必至矣。</p><p>上九，有孚於飲酒，無咎。濡其首，有孚失是。象曰：飲酒濡首，亦不知節也。</p><p>上孚於三，三震坎為酒，上反三成兌，坎流於兌口，有孚於酒也。三之上得正，無咎也。未濟之極，無極而自濟之理，非剛健之才，得時得位，上下孚應，終不濟也。上九君子有才而不當位，與六三相應，而無可濟之資，以其有孚矣，相與飲酒，樂天順命，以俟可濟之時，則於義無咎。上反三，乾首濡於酒中，則從樂眈肆，亦不知節矣。坎兌，節之象也。有孚若然，失是義矣。晉、魏之交，士多逃於麴櫱，無濟時之志，以故世復大亂。聖人之戒，不其深乎！易傳曰：人之處患，知其無可柰何，而放意不反者，豈安於義命者哉！周易下經豐傳第六。</p>',127)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
